#!/usr/bin/env python3
"""Check the exported message local key using generated bytes and the real decoder (WR-000502).

Key values are synthetic."""
import runpy
from pathlib import Path
import sqlite3
import struct
import subprocess
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from lib import outlook_intake as intake

CRATE = ROOT / 'vendor/hxprobe'
STORE = runpy.run_path(str(ROOT / 'ops/hxstore-observe-selftest.py'))['store']
EPOCH_TICKS = 621_355_968_000_000_000


def utf16(text):
    return (text + '\0').encode('utf-16le')


def message(key, sender='pat@example.test', sent=1_793_000_000, anchor_at=600,
            preview='Synthetic local key study preview text for one message', subject=None, html=None):
    """An expanded 00ca message header: the key repeated at +10, +30 and +38, a folder reference at +408,
    ItemClass after +454."""
    obj = bytearray(anchor_at)
    struct.pack_into('<H', obj, 0, 0x00ca)
    for at in (10, 30, 38):
        struct.pack_into('<Q', obj, at, key)
    if anchor_at >= 454:
        # Typed folder reference at +408 (class 004d, kind 2): folder 50 of account 7.
        struct.pack_into('<H', obj, 408, 0x004d)
        struct.pack_into('<QIQQQ', obj, 418, 50, 2, 7, 50, 7)
    encoded_sender = utf16(sender)
    obj[anchor_at - len(encoded_sender):anchor_at] = encoded_sender
    obj += utf16('IPM.Note')
    obj += struct.pack('<Q', sent * 10_000_000 + EPOCH_TICKS)
    if subject:
        obj += utf16(subject) * 2
    obj += utf16(preview)
    if html:
        obj += html.encode('utf-8')
    return bytes(obj)


class LocalKeyExportTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        subprocess.run(['cargo', 'build', '--locked'], cwd=CRATE, check=True, timeout=180)

    def export(self, *objects, columns='sender, sent_unix, copies, local_keys'):
        with tempfile.TemporaryDirectory() as tmp:
            source, target = Path(tmp) / 'synthetic.hxd', Path(tmp) / 'synthetic.db'
            source.write_bytes(STORE(b''.join(objects)))
            result = subprocess.run([str(CRATE / 'target/debug/hxprobe'), 'db', str(source), str(target)],
                                    capture_output=True, timeout=30)
            self.assertEqual(result.returncode, 0, result.stderr)
            with sqlite3.connect(target) as db:
                rows = db.execute(f'SELECT {columns} FROM messages ORDER BY sent_unix').fetchall()
                meta = dict(db.execute('SELECT key, value FROM meta'))
            return rows, meta

    def test_intake_preserves_subjects_of_distinct_decoder_items(self):
        subjects = [prefix + f'Synthetic suite review {group}' for group in range(125)
                    for prefix in ('', 'Re: ', 'Fw: ', 'Fwd: ')]
        with tempfile.TemporaryDirectory() as tmp:
            source, target = Path(tmp) / 'synthetic.hxd', Path(tmp) / 'synthetic.db'
            folder = bytearray(840)
            struct.pack_into('<H', folder, 0, 0x004d)
            struct.pack_into('<QIQQQ', folder, 10, 50, 2, 7, 50, 7)
            folder.extend(b'\1\1\1\1\0' + utf16('Inbox'))
            envelope = struct.pack('<HHIH', 5, 0x04d8, len(folder) + 10, 0) + folder
            source.write_bytes(STORE(envelope + b''.join(
                message(0x2000 + i, sender='owner@example.test', sent=1_793_000_000 - i * 30,
                        subject=subject) for i, subject in enumerate(subjects))))
            result = subprocess.run([str(CRATE / 'target/debug/hxprobe'), 'db', str(source), str(target)],
                                    capture_output=True, timeout=30)
            self.assertEqual(result.returncode, 0, result.stderr)
            _, mails, _ = intake._load(target, account_id=7)
            self.assertCountEqual([m['subject'] for m in mails], subjects)
            prepared = intake._best_copies(mails)
            self.assertCountEqual([intake.email_context(m, 'example.test')['subject']
                                   for m in prepared], subjects)

    def test_conflicting_or_unresolved_copy_ownership_never_admits_message(self):
        for unresolved in (False, True):
            with self.subTest(unresolved=unresolved), tempfile.TemporaryDirectory() as tmp:
                source, target = Path(tmp) / 'synthetic.hxd', Path(tmp) / 'synthetic.db'
                envelopes = []
                for folder_id, account in ((50, 7), (51, 8)):
                    folder = bytearray(840)
                    struct.pack_into('<H', folder, 0, 0x004d)
                    struct.pack_into('<QIQQQ', folder, 10, folder_id, 2, account, folder_id, account)
                    folder.extend(b'\1\1\1\1\0' + utf16('Inbox'))
                    envelopes.append(struct.pack('<HHIH', 5, 0x04d8, len(folder) + 10, 0) + folder)
                copy = bytearray(message(0x1001))
                struct.pack_into('<QIQQQ', copy, 418, 999 if unresolved else 51, 2, 8,
                                 999 if unresolved else 51, 8)
                source.write_bytes(STORE(b''.join(envelopes) + message(0x1001) + copy))
                subprocess.run([str(CRATE / 'target/debug/hxprobe'), 'db', str(source), str(target)],
                               capture_output=True, check=True, timeout=30)
                with sqlite3.connect(target) as db:
                    self.assertEqual(db.execute('SELECT copies FROM messages').fetchall(), [(2,)])
                meta, mails, _ = intake._load(target, account_id=7)
                self.assertEqual(mails, [])
                counter = 'mail_account_unresolved' if unresolved else 'mail_account_ambiguous'
                self.assertEqual(meta[counter], 1)

    def test_repeated_message_ids_are_neither_subjects_nor_recipients(self):
        rows, _ = self.export(message(0x1001, subject='<synthetic-id@example.test>'),
                              columns='subject, recipients')
        self.assertNotEqual(rows[0][0], '<synthetic-id@example.test>')
        self.assertNotIn('synthetic-id@example.test', rows[0][1] or '')

    def test_revisions_of_one_message_export_its_key(self):
        rows, meta = self.export(message(0x1001), message(0x1001))
        self.assertEqual(rows, [('pat@example.test', 1_793_000_000, 2, str(0x1001))])
        self.assertEqual((meta['messages_with_key'], meta['local_key_conflicts']), (1, 0))

    def test_distinct_messages_keep_distinct_keys(self):
        # A record's span reaches back to the previous anchor, so the later
        # record is written first to keep each send time its own.
        rows, _ = self.export(message(0x2002, sent=1_793_000_300),
                              message(0x3003, preview='A different synthetic opening for the second'))
        self.assertEqual([r[3] for r in rows], [str(0x3003), str(0x2002)])

    def test_identical_template_twins_export_separately(self):
        # Synthetic reproduction of the TEST-account W1/W2 observation.
        # Their sender and opening match, but their store-local keys differ.
        rows, meta = self.export(message(0x2002, sent=1_793_000_300), message(0x3003))
        self.assertEqual(rows, [('pat@example.test', 1_793_000_000, 1, str(0x3003)),
                                ('pat@example.test', 1_793_000_300, 1, str(0x2002))])
        self.assertEqual((meta['messages_with_key'], meta['local_key_conflicts']), (2, 0))

    def test_identical_sender_and_time_do_not_merge_distinct_keys(self):
        # Sender plus send time joins these; the keys say they are two store items.
        rows, meta = self.export(message(0x2002), message(0x3003))
        self.assertEqual(sorted(rows), [('pat@example.test', 1_793_000_000, 1, str(0x3003)),
                                        ('pat@example.test', 1_793_000_000, 1, str(0x2002))])
        self.assertEqual((meta['messages_with_key'], meta['local_key_conflicts']), (2, 0))

    def test_preview_does_not_join_another_keys_full_body(self):
        preview = 'Synthetic local key study preview text for one message'
        rows, _ = self.export(
            message(0x2002, sent=1_793_000_300, subject='Full subject',
                    html=f'<html><body>{preview}</body></html>'),
            message(0x3003, subject='Preview subject'),
            columns='subject, body_kind, copies, local_keys')
        self.assertEqual(rows, [('Preview subject', 'preview', 1, str(0x3003)),
                                ('Full subject', 'full', 1, str(0x2002))])

    def test_same_key_and_unkeyed_copies_keep_existing_merge_behavior(self):
        for key in (0x2002, 0):
            with self.subTest(key=key):
                rows, _ = self.export(message(key, sent=1_793_000_300), message(key))
                self.assertEqual(rows, [('pat@example.test', 1_793_000_000, 2, str(key) if key else None)])

    def test_same_key_and_unkeyed_previews_still_join_their_full_body(self):
        preview = 'Synthetic local key study preview text for one message'
        for key in (0x2002, 0):
            with self.subTest(key=key):
                rows, _ = self.export(
                    message(key, sent=1_793_000_300, subject='Full subject',
                            html=f'<html><body>{preview}</body></html>'),
                    message(key, subject='Preview subject'),
                    columns='subject, body_kind, copies, local_keys')
                self.assertEqual(rows, [('Full subject', 'full', 2, str(key) if key else None)])

    def test_unkeyed_rows_cannot_bridge_distinct_keyed_items(self):
        rows, meta = self.export(message(0x2002, sent=1_793_000_300), message(0), message(0x3003))
        self.assertEqual(len(rows), 3)
        self.assertCountEqual([r[2:] for r in rows], [(1, str(0x2002)), (1, None), (1, str(0x3003))])
        self.assertEqual(meta['local_key_conflicts'], 0)

    def test_an_anchor_inside_the_fixed_header_or_without_a_header_gets_no_key(self):
        bare = bytearray(message(0x4004, preview='Another synthetic opening without any header'))
        bare[0] = 0xcb
        rows, meta = self.export(message(0x5005, anchor_at=400, sent=1_793_000_100), bare)
        self.assertEqual([r[3] for r in rows], [None, None])
        self.assertEqual(meta['messages_with_key'], 0)


if __name__ == '__main__':
    unittest.main()
